#include <iostream>
using namespace std;

struct ChainNode {
    int data;
    ChainNode *next;
    ChainNode(int d) : data(d), next(0) {}
};

int main() {
    int n;
    if (!(cin >> n)) return 0;

    ChainNode *first = 0, *rear = 0;
    for (int i = 0; i < n; i++) {
        int v;
        cin >> v;
        ChainNode *s = new ChainNode(v);
        if (first == 0) first = rear = s;
        else { rear->next = s; rear = s; }
    }

    // 就地逆置：把每个结点摘下来头插到新表
    ChainNode *p = first, *q = 0;
    first = 0;
    while (p != 0) {
        q = p->next;        // ① 记住后继
        p->next = first;    // ② 头插
        first = p;          // ③ 更新表头
        p = q;              // ④ 继续
    }

    if (first == 0) {
        cout << "empty\n";
        return 0;
    }
    for (ChainNode *t = first; t != 0; t = t->next)
        cout << t->data << (t->next == 0 ? '\n' : ' ');
    return 0;
}
